class Solution {
public:
    vector<int> numMovesStones(int a, int b, int c) {
        vector<int> v = {a, b, c};
        sort(v.begin(), v.end());
        int x = v[0], y = v[1], z = v[2];
        int min_moves = 2;
        if (z - x == 2) min_moves = 0;
        else if (y - x <= 2 || z - y <= 2) min_moves = 1;
        int max_moves = (z - y - 1) + (y - x - 1);
        return {min_moves, max_moves};
    }
};

class Solution {
    public int[] numMovesStones(int a, int b, int c) {
        int[] v = new int[]{a, b, c};
        Arrays.sort(v);
        int x = v[0], y = v[1], z = v[2];
        int minMoves = 2;
        if (z - x == 2) minMoves = 0;
        else if (y - x <= 2 || z - y <= 2) minMoves = 1;
        int maxMoves = (z - y - 1) + (y - x - 1);
        return new int[]{minMoves, maxMoves};
    }
}

var numMovesStones = function(a, b, c) {
    const [x, y, z] = [a, b, c].sort((m, n) => m - n);
    let minMoves = 2;
    if (z - x === 2) minMoves = 0;
    else if (y - x <= 2 || z - y <= 2) minMoves = 1;
    const maxMoves = (z - y - 1) + (y - x - 1);
    return [minMoves, maxMoves];
};
